def skeleton_contents() -> bytes:
    """빈 당기 칸은 DART 편집기가 쓰는 모양(<TD></TD>)으로 둔다."""
    return _document().replace(b'<TD ALIGN="LEFT"/>', b'<TD ALIGN="RIGHT"></TD>')


def _document() -> bytes:
    return document(
        p("합성 테스트 문서"),
        title("재무제표", 2),
        statement_title_table("재 무 상 태 표"),
        table([HEAD_BS], _rows(BS), unit="원"),
        statement_title_table("손 익 계 산 서"),
        table([HEAD_PL], _rows(IS), unit="원"),
        statement_title_table("자 본 변 동 표"),
        table([SCE_HEAD], SCE, unit="원"),
        statement_title_table("현 금 흐 름 표"),
        table([HEAD_PL], _rows(CF), unit="원"),
        title("주석", 3),
        p("제 2(당) 기말 주석"),
        p("1. 일반사항\n합성테스트 주식회사는 테스트를 위해 설립되었습니다."),
        p("4. 현금및현금성자산\n당기말과 전기말 현재 현금및현금성자산의 내역은 다음과 같습니다."),
        table([["구  분", "당기말", "전기말"]], NOTE4),
    )


def write_skeleton(path) -> str:
    write_dsd(path, skeleton_contents())
    return str(path)


def tb_dict(rows=TB) -> dict:
    return {"schema": "dsdxlsx.tb/1", "period": {"cur": "2026.12.31", "pri": "2025.12.31"},
            "rows": [{"code": c, "name": n, "settle": s, "pri": pri, "cur": cur, "aje": 0} for c, n, s, pri, cur in rows]}


def write_tb(path, rows=TB) -> str:
    with open(path, "w", encoding="utf-8") as f:
        json.dump(tb_dict(rows), f, ensure_ascii=False)
    return str(path)
